// The three extra CTA blob variants (MOTION_SPEC 10: four hand-tuned variants,
// generated by moving the existing control points by +/-24px).
//
// The variants are generated deterministically from CTA_BLOB_PATH rather than
// typed by hand: each cubic segment's two control points are offset along the
// segment's chord normal by a 24px sine lobe, three phases apart. The anchors
// never move, so the path stays closed and smooth and MorphSVGPlugin sees an
// identical command structure (M + 11 C + Z) for every variant. Offsets are
// capped at +/-24px per control point, matching the spec.

import { CTA_BLOB_PATH } from './blobPath';

const AMPLITUDE = 24; // MOTION_SPEC 10: control points move by +/-24px
const PHASES = [0, (2 * Math.PI) / 3, (4 * Math.PI) / 3] as const;

type Point = readonly [number, number];
type Cubic = {
  control1: Point;
  control2: Point;
  end: Point;
};

function parsePath(d: string): { start: Point; segments: Cubic[] } {
  const numbers = (d.match(/-?\d+(?:\.\d+)?/g) ?? []).map(Number);
  const start: Point = [numbers[0], numbers[1]];
  const segments: Cubic[] = [];
  for (let index = 2; index + 5 < numbers.length; index += 6) {
    segments.push({
      control1: [numbers[index], numbers[index + 1]],
      control2: [numbers[index + 2], numbers[index + 3]],
      end: [numbers[index + 4], numbers[index + 5]],
    });
  }
  return { start, segments };
}

const fmt = (value: number) => value.toFixed(3).replace(/0+$/, '').replace(/\.$/, '');

function buildVariant(phase: number): string {
  const { start, segments } = parsePath(CTA_BLOB_PATH);
  const count = segments.length;
  const parts: string[] = [`M${fmt(start[0])} ${fmt(start[1])}`];
  let anchor: Point = start;

  segments.forEach((segment, index) => {
    const chordX = segment.end[0] - anchor[0];
    const chordY = segment.end[1] - anchor[1];
    const length = Math.hypot(chordX, chordY) || 1;
    const normalX = -chordY / length;
    const normalY = chordX / length;
    const offset = AMPLITUDE * Math.sin((2 * Math.PI * index) / count + phase);

    const control1: Point = [
      segment.control1[0] + normalX * offset,
      segment.control1[1] + normalY * offset,
    ];
    const control2: Point = [
      segment.control2[0] + normalX * offset,
      segment.control2[1] + normalY * offset,
    ];

    parts.push(
      `C${fmt(control1[0])} ${fmt(control1[1])} ${fmt(control2[0])} ${fmt(control2[1])} ${fmt(segment.end[0])} ${fmt(segment.end[1])}`,
    );
    anchor = segment.end;
  });

  return `${parts.join('')}Z`;
}

/** Original + three variants, in the order the idle morph visits them. */
export const BLOB_VARIANTS: readonly [string, string, string, string] = [
  CTA_BLOB_PATH,
  buildVariant(PHASES[0]),
  buildVariant(PHASES[1]),
  buildVariant(PHASES[2]),
];
